import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Typography } from 'antd';
import cn from 'classnames';

import { OfferRead } from '../../api/codegen.api';
import { OfferSubBlock } from '../OfferSubBlock/OfferSubBlock';

import styles from './OfferOther.module.scss';

interface IOfferOtherProps extends HTMLAttributes<HTMLDivElement> {
	offer: OfferRead;
}

export const OfferOther: FC<IOfferOtherProps> = ({ className, offer, ...props }) => {
	const { t } = useTranslation();

	return (
		<div {...props} className={cn(className, styles.content)}>
			<Typography.Title level={2}>{t('Other')}</Typography.Title>
			<OfferSubBlock title={t('Additional terms')} descriptions={offer?.additional_terms}></OfferSubBlock>
		</div>
	);
};
