import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Tag, Typography } from 'antd';
import cn from 'classnames';

import AllowedIcon from 'assets/images/icons/allowed.svg?react';
import DisabledIcon from 'assets/images/icons/disabled.svg?react';
import { TRAFFICS } from 'shared/consts';

import { OfferTrafficType } from '../../api/codegen.api';

import styles from './OfferTrafficTypes.module.scss';

interface IOfferTrafficTypesProps extends HTMLAttributes<HTMLDivElement> {
	trafficTypes: OfferTrafficType[];
}

export const OfferTrafficTypes: FC<IOfferTrafficTypesProps> = ({ className, trafficTypes, ...props }) => {
	const { t } = useTranslation();
	const allowedTrafficTypes = trafficTypes?.filter(({ allowed }) => allowed);
	const forbiddenTrafficTypes = trafficTypes?.filter(({ allowed }) => !allowed);

	const formatTrafficType = (trafficType: keyof typeof TRAFFICS): string => TRAFFICS[trafficType] || t('Other');

	return (
		<div {...props} className={cn(className, styles.content)}>
			{!!allowedTrafficTypes?.length && (
				<div className={styles.traffics}>
					<span className={styles.title}>
						<AllowedIcon />
						<Typography.Text>{t('Allowed types of traffic')}:</Typography.Text>
					</span>
					{allowedTrafficTypes.map((type) => (
						<Tag key={`key-${type?.traffic_type?.slug}`}>
							{formatTrafficType(type?.traffic_type?.slug as keyof typeof TRAFFICS)}
						</Tag>
					))}
				</div>
			)}
			{!!forbiddenTrafficTypes?.length && (
				<div className={styles.traffics}>
					<span className={styles.title}>
						<DisabledIcon />
						<Typography.Text>{t('Forbidden types of traffic')}:</Typography.Text>
					</span>
					{forbiddenTrafficTypes?.map((type) => (
						<Tag key={`key-${type?.traffic_type?.slug}`}>
							{formatTrafficType(type?.traffic_type?.slug as keyof typeof TRAFFICS)}
						</Tag>
					))}
				</div>
			)}
		</div>
	);
};
