import { FC, Fragment, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Tooltip, Typography } from 'antd';
import cn from 'classnames';

import AllowedIcon from 'assets/images/icons/allowed.svg?react';
import DisabledIcon from 'assets/images/icons/disabled.svg?react';
import InfoIcon from 'assets/images/info.svg?react';

import { OfferRead } from '../../api/codegen.api';

import styles from './OfferTrafficSecurity.module.scss';

interface IOfferTrafficSecurityProps extends HTMLAttributes<HTMLDivElement> {
	offer: OfferRead;
}

export const OfferTrafficSecurity: FC<IOfferTrafficSecurityProps> = ({ className, offer, ...props }) => {
	const { t } = useTranslation();
	const trafficsSecurity = [
		{
			name: t('MMP link'),
			text: t(
				'URL or connection point for tracking campaign performance across devices via Mobile Measurement Partners.',
			),
			value: offer?.mmp_link,
			key: 'mmpLink',
		},
		{
			name: t('VTA'),
			text: t(
				'View-Through Attribution: Measures the impact of ads that are viewed, not clicked, indicating their influence on user actions.',
			),
			value: offer?.vta,
			key: 'vta',
		},
		{
			name: t('CRM'),
			text: t("Indicates the use of advertiser's CRM resources for action approval and fraud detection"),
			value: offer?.crm,
			key: 'crm',
		},
		{
			name: t('Agency Access'),
			text: t('Indicates if agency access will be shared in the tracker.'),
			value: offer?.agency_access,
			key: 'agencyAccess',
		},
	];

	return (
		<div {...props} className={cn(className, styles.content)}>
			<Typography.Title level={2}>{t('Traffic security')}</Typography.Title>
			<div className={styles.list}>
				{trafficsSecurity.map((traffic) => (
					<div className={styles.item} key={traffic?.key}>
						<div className={styles.subtitle}>
							<Typography.Text>{traffic.name}</Typography.Text>
							<Tooltip title={traffic.text}>
								<InfoIcon />
							</Tooltip>
						</div>
						<div className={cn(styles.subtitle)}>
							{traffic?.value !== undefined && (
								<Fragment>
									<Typography.Text type="secondary">{traffic?.value ? t('Yes') : t('No')}</Typography.Text>
									{traffic?.value ? <AllowedIcon /> : <DisabledIcon />}
								</Fragment>
							)}
						</div>
					</div>
				))}
			</div>
		</div>
	);
};
