import { FC, HTMLAttributes, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useDispatch } from 'react-redux';

import { Button, Tooltip, Typography } from 'antd';
import cn from 'classnames';

import { AppDispatch } from 'app/appStore';
import noImageIcon from 'assets/images/no-image.svg';
import { JoinedSourceList, openJoinModal } from 'features/JoinOffer';
import { CATEGORIES } from 'shared/consts';
import { useMedia } from 'shared/hooks';

import { OfferRead } from '../../api/codegen.api';

import styles from './OfferHeader.module.scss';

interface IOfferHeaderProps extends HTMLAttributes<HTMLDivElement> {
	offer: OfferRead;
}

export const OfferHeader: FC<IOfferHeaderProps> = ({ className, offer, ...props }) => {
	const { t } = useTranslation();
	const isMobile = useMedia();
	const dispatch = useDispatch<AppDispatch>();
	const [showSources, setShowSources] = useState(false);

	return (
		<div {...props} className={cn(className, styles.header)}>
			<div className={styles.card}>
				<div className={styles.logo}>
					<img src={offer?.image || noImageIcon} alt={`${offer?.name}`} height={'84px'} width={'84px'}></img>
					<div className={styles.logo_desc}>
						<Typography.Title level={5}>{offer.name}</Typography.Title>
						<Typography.Text type="secondary" style={{ fontSize: '14px' }}>
							{offer?.categories?.map(({ slug }) => CATEGORIES[slug]).join(', ')}
						</Typography.Text>
					</div>
				</div>
				<div className={styles.btns}>
					<Button type="primary" block={isMobile} onClick={() => dispatch(openJoinModal(offer))}>
						{t('Get feed')}
					</Button>
					<div className={styles.cap}>
						<Tooltip
							title={t(`Cap is the limit of sources set by Advertiser.
                            If you see 'Cap is reached', you will be able to Join the offer anyway, but will have to wait,
                            when Advertiser extend the cap.`)}>
							<Typography.Text type="secondary">
								{offer?.cap_is_reached ? t('Cap is reached') : t(`Cap isn't reached`)}
							</Typography.Text>
						</Tooltip>
					</div>
				</div>
			</div>
			{showSources && <JoinedSourceList sources={offer?.sources_relations} isOfferDetails={true} />}
			{!!offer?.sources_relations?.length && (
				<Button type="link" className={styles.toggleSource} onClick={() => setShowSources(!showSources)}>
					{!showSources ? t('Show joined sources') : t('Hide joined sources')}
				</Button>
			)}
		</div>
	);
};
