import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { useParams } from 'react-router-dom';

import {
	OfferAbout,
	OfferHeader,
	OfferOther,
	OfferTabs,
	OfferTrafficSecurity,
	OfferTrafficTypes,
	useOfferDetails,
	useOffersRetrieveQuery,
} from 'entities/Offer';
import { SourceFilter } from 'features/Filters';
import { JoinOffer } from 'features/JoinOffer';
import { OverlayLoader, PageTitle } from 'shared/ui';

import styles from './Offer.module.scss';

interface IOfferProps extends HTMLAttributes<HTMLDivElement> {}

export const Offer: FC<IOfferProps> = () => {
	const { t } = useTranslation();
	const { slug } = useParams();
	const { data, isFetching: offerIsFetching } = useOffersRetrieveQuery(slug as string);
	const { updatedOffer } = useOfferDetails(data, true);

	return (
		<>
			<PageTitle component={<SourceFilter />} type="filled">
				{t('Offer page')}
			</PageTitle>
			<div className={styles.offer}>
				{offerIsFetching && <OverlayLoader />}
				<OfferTabs id="about" />
				<OfferHeader offer={updatedOffer} />
				<OfferTrafficTypes trafficTypes={updatedOffer?.offer_traffic_types} />
				<OfferAbout offer={updatedOffer} />
				<OfferTrafficSecurity id="traffic-security" offer={updatedOffer} />
				<OfferOther id="other" offer={updatedOffer} />
			</div>
			<JoinOffer />
		</>
	);
};

export default Offer;
