import { FC, HTMLAttributes, ReactNode } from 'react';

import { Typography } from 'antd';
import cn from 'classnames';

import styles from './OfferSubBlock.module.scss';

interface IOfferSubBlockProps extends HTMLAttributes<HTMLDivElement> {
	title: string;
	descriptions?: string;
	prevDescriptions?: ReactNode;
}

export const OfferSubBlock: FC<IOfferSubBlockProps> = ({
	className,
	title,
	descriptions,
	prevDescriptions,
	children,
	...props
}) => {
	return (
		<div {...props} className={cn(className, styles.content)}>
			<div className={styles.body}>
				<Typography.Title level={3}>{title}</Typography.Title>
				{prevDescriptions && <p className={styles.prevDesc}>{prevDescriptions}</p>}
				{descriptions && <div dangerouslySetInnerHTML={{ __html: descriptions }}></div>}
			</div>
			{children}
		</div>
	);
};
