import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { HashLink } from 'react-router-hash-link';

import { Button } from 'antd';
import cn from 'classnames';

import styles from './OfferTabs.module.scss';

interface IOfferTabsProps extends HTMLAttributes<HTMLDivElement> {}

export const OfferTabs: FC<IOfferTabsProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const tabs = [
		{ hash: '#about', text: t('About offer') },
		{ hash: '#payout-details', text: t('Payout details') },
		{ hash: '#traffic-security', text: t('Traffic security') },
		{ hash: '#reatives', text: t('Creatives') },
		{ hash: '#other', text: t('Other') },
	];

	return (
		<div {...props} className={cn(className, styles.tabs)}>
			{tabs.map((tab, idx) => (
				<HashLink key={`key_${tab.hash}`} to={tab.hash}>
					<Button color="default" variant={idx ? 'text' : 'solid'}>
						{tab.text}
					</Button>
				</HashLink>
			))}
		</div>
	);
};
